// Species are explicit; unimplemented species never inherit dog milestones.
export const SPECIES={dog:{id:'dog',label:'개',scientificName:'Canis lupus familiaris',source:{id:'merck-development',url:'https://www.merckvetmanual.com/behavior/behavior-of-dogs/social-behavior-of-dogs',reviewed:'2025-09',retrieved:'2026-10-16',appliesTo:'가정견',uncertainty:'발달 기간은 유전·환경·건강에 따라 달라짐. 개별 날짜와 귀의 발달일은 게임 보간값.'},development:{neonatal:[0,13],transition:[13,19],socialization:[19,84],weaning:[46,54],sexualMaturity:[180,270],socialMaturity:[365,1095]},reproduction:{source:'merck-reproduction',gestationFromConception:[62,64],uncertainty:'주기·임신 확률·새끼 수·최대 두 배의 새끼 제한은 게임용 설정'},capabilities:{walk:20,exploreNest:35,independentOutside:90}}};
export function speciesOf(s){const p=SPECIES[s.species||'dog'];if(!p)throw Error('지원하지 않는 동물 종');return p;}
export function developmentStage(s){const d=s.day;return d<13?'온기와 돌봄에 의지하는 시기':d<20?'눈과 귀가 열리는 시기':d<84?'함께 놀며 배우는 시기':d<180?'몸을 쓰며 탐색하는 시기':d<365?'성숙해 가는 시기':d<2920?'성견기':'노년기';}
export function canAct(s,kind){const p=speciesOf(s);return s.alive&&s.day>=(p.capabilities[kind]??0)&&(!s.medical?.episode||kind==='rest')&&(!(s.clinical?.active&&['recovery','rehabilitation'].includes(s.clinical.active.stage))||kind==='rest');}
